import Foundation
import Shared

/// Layer ④: paste via the pasteboard, then put the user's clipboard back exactly (all items, all types,
/// images included). The restore is skipped — never clobbering — if `changeCount` shows anything else
/// wrote to the pasteboard after us (clipboard managers, the user copying mid-paste).
///
/// N18 — our write carries the nspasteboard.org transient, auto-generated and concealed markers so
/// clipboard managers (Maccy, Paste, Raycast, Alfred) neither record nor show the dictation.
public final class ClipboardPaster {
    public enum RestoreResult: Equatable, Sendable { case restored, skippedChangeCountMismatch, nothingToRestore }

    private let system: SystemAccess
    /// N18 — how long the target app gets to read the paste before the user's clipboard comes back.
    /// Electron/Chromium read the pasteboard asynchronously; too short and they paste the old clipboard.
    public var settleMilliseconds = 200

    public init(system: SystemAccess) { self.system = system }

    @discardableResult
    public func paste(_ text: String, toPID pid: Int32) throws -> RestoreResult {
        try paste(toPID: pid) { PasteboardMarkers.writeTransient(text, to: system) }
    }

    /// N24 — pastes a rich payload (TSV + HTML table, or Markdown). Falls back to the payload's plain
    /// text on a system that cannot write several types. Same markers, settle and restore as `paste`.
    @discardableResult
    public func paste(_ payload: RichPastePayload, toPID pid: Int32) throws -> RestoreResult {
        try paste(toPID: pid) {
            if let writer = system as? RichPasteboardWriting { return writer.writeTransientPasteboard(types: payload.types) }
            return PasteboardMarkers.writeTransient(payload.plainText ?? "", to: system)
        }
    }

    private func paste(toPID pid: Int32, write: () -> Int) throws -> RestoreResult {
        let saved = system.readPasteboard()
        let ours = write()
        do {
            try system.postKeyCombo(.paste, toPID: pid)
        } catch {
            _ = restore(saved, ourChangeCount: ours)
            throw error
        }
        system.settle(milliseconds: settleMilliseconds)   // let the target app consume the paste before we swap back
        return restore(saved, ourChangeCount: ours)
    }

    private func restore(_ saved: PasteboardSnapshot, ourChangeCount: Int) -> RestoreResult {
        guard system.pasteboardChangeCount == ourChangeCount else {
            Log.injection.warning("pasteboard changed during paste; leaving it alone")
            return .skippedChangeCountMismatch
        }
        system.restorePasteboard(saved)
        return saved.items.isEmpty ? .nothingToRestore : .restored
    }
}

/// N18 — the nspasteboard.org markers that tell clipboard managers to skip an entry.
public enum PasteboardMarkers {
    /// Not meant to persist: the app will restore the previous contents shortly.
    public static let transient = "org.nspasteboard.TransientType"
    /// Written by software, not by a user's Copy.
    public static let autoGenerated = "org.nspasteboard.AutoGeneratedType"
    /// May be private: never show or store it.
    public static let concealed = "org.nspasteboard.ConcealedType"
    public static let all = [transient, autoGenerated, concealed]

    /// Writes `text` with every marker when `system` can, else a plain string (test doubles).
    @discardableResult
    public static func writeTransient(_ text: String, to system: SystemAccess) -> Int {
        if let writer = system as? TransientPasteboardWriting { return writer.writeTransientPasteboard(string: text) }
        return system.writePasteboard(string: text)
    }
}

/// N18 — a pasteboard write that carries `PasteboardMarkers.all`. A separate protocol so existing
/// `SystemAccess` conformers compile unchanged. User-initiated copies (held text → Copy) keep using
/// the plain `writePasteboard`: those are meant to be remembered.
public protocol TransientPasteboardWriting: AnyObject {
    /// Writes a plain string plus the markers and returns the resulting changeCount.
    @discardableResult func writeTransientPasteboard(string: String) -> Int
}
